const input = $input.all();
return input.map(item => {
  if (item.json && item.json.choices && item.json.choices[0] && item.json.choices[0].message) {
    return { json: { content: item.json.choices[0].message.content } };
  } else {
    return { json: { content: 'Content not available' } };
  }
});

// Enhanced audio processing with better error handling

// Log the entire input for debugging
console.log("Audio Processing Input:", JSON.stringify(items[0].json));

// First, try to find the file in the multipart form data
let audioFile;
let foundFile = false;

// Check if file exists in binary data
if (items[0].binary) {
  const binaryKeys = Object.keys(items[0].binary);
  if (binaryKeys.length > 0) {
    audioFile = items[0].binary[binaryKeys[0]];
    foundFile = true;
    console.log("Found audio in binary data:", audioFile.fileName, audioFile.mimeType);
  }
}

// If not found in binary, try to extract from form data
if (!foundFile && items[0].json && items[0].json.body) {
  const formData = items[0].json.body;
  console.log("Form data keys:", Object.keys(formData));

  if (formData.file) {
    try {
      // Extract file from form data
      audioFile = formData.file;
      foundFile = true;
      console.log("Found audio in form data:", audioFile);
    } catch (error) {
      console.error("Error extracting file from form data:", error);
    }
  }
}

// If still no file found, throw detailed error
if (!foundFile) {
  console.error("No audio file found in request");
  throw new Error("No audio file found in request");
}

// Ensure proper file format
let fileName = "audio_" + Date.now() + ".webm";
let mimeType = "audio/webm";

// Return properly formatted binary data
return {
  json: {
    contentType: "audio",
    route: "audio"
  },
  binary: {
    file: {
      ...audioFile,
      fileName: fileName,
      mimeType: mimeType
    }
  }
};

try {
    const response = items[0].json;
    console.log("Transcription response:", JSON.stringify(response));

    // Fix: Look for text in the body object instead
    if (!response || !response.body || !response.body.text) {
        throw new Error('Invalid transcription response: ' + JSON.stringify(response));
    }

    return [{
        json: {
            responseText: response.body.text.trim()
        }
    }];
} catch (error) {
    console.error('Transcription formatting error:', error);
    throw new Error('Failed to process transcription');
}

// Process the image data from form data
console.log('Image processing started');

// Log to help with debugging
console.log('Content type received:', items[0].json.body?.contentType);

// Find the file in binary data or form data
let imageFile;
let foundFile = false;

// Check binary data first
if (items[0].binary) {
    const binaryKeys = Object.keys(items[0].binary);
    if (binaryKeys.length > 0) {
        imageFile = items[0].binary[binaryKeys[0]];
        foundFile = true;
        console.log('Found image in binary data:', imageFile.fileName, imageFile.mimeType);
    }
}

// If not found in binary, try to extract from form data
if (!foundFile && items[0].json && items[0].json.body) {
    const formData = items[0].json.body;
    console.log('Form data keys:', Object.keys(formData));

    if (formData.file) {
        imageFile = formData.file;
        foundFile = true;
        console.log('Found image in form data');
    }
}

// If still no file found, throw error
if (!foundFile) {
    console.error('No image file found in request');
    throw new Error('No image file found in request');
}

// Pass through the image file data
return {
    json: {
        message: items[0].json.body?.message || 'What is in this image?',
        userId: items[0].json.body?.userId || 'unknown-user'
    },
    binary: {
        file: imageFile
    }
};

const response = items[0].json;
console.log('Response keys:', Object.keys(response || {}));
console.log('Response type:', typeof response);

// HTTP request response can be in different formats
let html = response?.data || response?.body || response;

// If it's still an object, try stringifying it
if (typeof html === 'object' && html !== null) {
  console.log('Response is object, checking for text property...');
  html = html?.text || JSON.stringify(html);
}

if (!html || typeof html !== 'string') {
  console.error('Invalid response format:', typeof response, 'Keys:', Object.keys(response || {}));
  return [{ json: { error: 'No HTML content from page' } }];
}

if (html.length === 0) {
  return [{ json: { error: 'Empty HTML response' } }];
}

console.log('✓ HTML fetched, length:', html.length);

// Try to extract JSON-LD recipe data from ALL script tags (not just first)
const jsonLdRegex = /<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi;
let jsonLdMatches = [];
let match;
while ((match = jsonLdRegex.exec(html)) !== null) {
  jsonLdMatches.push(match[1]);
}

let recipeData = null;

// Try to find Recipe in all JSON-LD blocks
for (const jsonLdText of jsonLdMatches) {
  try {
    const jsonLd = JSON.parse(jsonLdText.trim());
    let recipe = null;

    // Check if it's directly a Recipe or inside an array
    if (Array.isArray(jsonLd)) {
      recipe = jsonLd.find(item => item['@type'] === 'Recipe');
    } else if (jsonLd['@type'] === 'Recipe') {
      recipe = jsonLd;
    } else if (jsonLd['@graph'] && Array.isArray(jsonLd['@graph'])) {
      recipe = jsonLd['@graph'].find(item => item['@type'] === 'Recipe');
    }

    if (recipe) {
      // Better handling of recipeInstructions - could be various formats
      let instructions = '';
      if (recipe.recipeInstructions) {
        if (typeof recipe.recipeInstructions === 'string') {
          instructions = recipe.recipeInstructions;
        } else if (Array.isArray(recipe.recipeInstructions)) {
          instructions = recipe.recipeInstructions
            .map(item => typeof item === 'string' ? item : item.text || item.description || '')
            .filter(text => text.length > 0)
            .join('\n');
        }
      }

      recipeData = {
        title: recipe.name || 'Untitled Recipe',
        ingredients_text: recipe.recipeIngredient?.join('\n') || '',
        instructions_text: instructions,
        servings: recipe.recipeYield ? recipe.recipeYield.toString().replace(/\D/g, '') : '4',
        prep_time: recipe.prepTime?.match(/\d+/)?.[0] || recipe.cookTime?.match(/\d+/)?.[0] || '30',
        image_url: recipe.image?.url || recipe.image?.[0]?.url || recipe.image || undefined,
        source_url: $('Webhook').item.json.body.message
      };
      console.log('✓ Successfully extracted JSON-LD recipe data');
      break;
    }
  } catch (error) {
    console.error('JSON-LD parsing error for block:', error.message);
  }
}

// Fallback: Improved regex parsing if JSON-LD not found
if (!recipeData) {
  console.log('JSON-LD not found, trying regex fallback...');
  try {
    // Extract title from various possible HTML tags
    const titleMatch = html.match(/<h1[^>]*>([^<]*)<\/h1>/i) || 
                       html.match(/<meta\s+property=["']og:title["']\s+content=["']([^"']*)["']/i);

    // More flexible ingredient and instruction extraction
    // Look for lists or divs that might contain them
    const ingredientPatterns = [
      /<(ul|ol)[^>]*(?:class|id)[^>]*ingredient[^>]*>([\s\S]*?)<\/(ul|ol)>/i,
      /<div[^>]*(?:class|id)[^>]*ingredient[^>]*>([\s\S]*?)<\/div>/i,
      /<(li|p)[^>]*>\s*([\d\s\w]*(?:cup|tbsp|tsp|g|kg|ml|l|oz)[\s\w]*[^<]*?)<\/(li|p)>/gi
    ];

    const instructionPatterns = [
      /<(ul|ol)[^>]*(?:class|id)[^>]*instruction[^>]*>([\s\S]*?)<\/(ul|ol)>/i,
      /<div[^>]*(?:class|id)[^>]*instruction[^>]*>([\s\S]*?)<\/div>/i,
      /<(ol|ul)[^>]*>([\s\S]*?)<\/(ol|ul)>/i
    ];

    let ingredientsText = '';
    for (const pattern of ingredientPatterns) {
      const match = html.match(pattern);
      if (match) {
        ingredientsText = (match[2] || match[0])
          .replace(/<[^>]*>/g, '')
          .split('\n')
          .map(line => line.trim())
          .filter(line => line.length > 0)
          .join('\n');
        if (ingredientsText.length > 20) break;
      }
    }

    let instructionsText = '';
    for (const pattern of instructionPatterns) {
      const match = html.match(pattern);
      if (match) {
        instructionsText = (match[2] || match[0])
          .replace(/<[^>]*>/g, '')
          .split('\n')
          .map(line => line.trim())
          .filter(line => line.length > 0)
          .join('\n');
        if (instructionsText.length > 20) break;
      }
    }

    // Extract servings and prep time from common patterns
    const servingsMatch = html.match(/(?:serves|servings?)[:\s]+([\d]+)/i);
    const prepTimeMatch = html.match(/prep\s+time[:\s]+(?:PT)?(\d+)(?:M|m)/i) ||
                         html.match(/prep[:\s]+([\d]+)\s*(?:mins?|minutes?)/i);
    const cookTimeMatch = html.match(/cook\s+time[:\s]+(?:PT)?(\d+)(?:M|m)/i) ||
                         html.match(/cooking?[:\s]+([\d]+)\s*(?:mins?|minutes?)/i);

    recipeData = {
      title: titleMatch?.[1]?.trim() || 'Recipe from URL',
      ingredients_text: ingredientsText,
      instructions_text: instructionsText,
      servings: servingsMatch?.[1] || '4',
      prep_time: prepTimeMatch?.[1] || cookTimeMatch?.[1] || '30',
      image_url: html.match(/<meta\s+property=["']og:image["']\s+content=["']([^"']*)["']/i)?.[1],
      source_url: $('Webhook').item.json.body.message
    };
    console.log('✓ Used fallback regex parsing');
  } catch (error) {
    console.error('Regex parsing error:', error.message);
    return [{ json: { error: 'Could not parse recipe from URL' } }];
  }
}

return [{
  json: recipeData || { error: 'Could not extract recipe data' }
}];

const recipe = items[0].json;

// Check if there was an error in the previous steps
if (recipe.error) {
  console.error('Recipe extraction error:', recipe.error);
  return [{ json: { error: recipe.error } }];
}

// Check if we have any recipe data at all
if (!recipe || !recipe.title) {
  console.error('No valid recipe data to format');
  return [{ json: { error: 'No recipe data available to format' } }];
}

// Clean and normalize the recipe data
return [{
  json: {
    message: `Great! "${recipe.title?.trim()}" has been saved to your library! You can now view it in your My Recipes section, edit it, adjust servings, and add more ingredients whenever you'd like.`,
    recipe: {
      title: recipe.title?.trim() || 'Untitled Recipe',
      ingredients_text: recipe.ingredients_text?.trim() || '',
      instructions_text: recipe.instructions_text?.trim() || '',
      servings: parseInt(recipe.servings) || 4,
      prep_time: parseInt(recipe.prep_time) || 30,
      image_url: recipe.image_url,
      source_url: recipe.source_url
    }
  }
}];

const recipeText = items[0].json.body.message;
console.log('Parsing recipe content...');

// Split by common separators and normalize
const lines = recipeText.split(/\n|\r\n/).map(line => line.trim()).filter(line => line.length > 0);

let title = '';
let ingredientsText = '';
let instructionsText = '';
let servings = '4';
let prepTime = '30';

// Try to find title from first few non-empty lines or common patterns
const titlePatterns = [
  /^(?:title|recipe|name)[:\s]+(.+)$/i,
  /^#{1,3}\s+(.+)$/,  // Markdown headers
  /^(?:my\s+)?([a-z][^0-9]*?)(?:\s+recipe|\s+-|$)/i  // General title
];

let ingredientsSectionStart = -1;
let instructionsSectionStart = -1;

// Find section boundaries
const ingredientKeywords = /^(?:ingredients|components|what you need|you will need|supplies)[:\s]*$/i;
const instructionKeywords = /^(?:instructions|directions|method|how to|steps|procedure|cooking|cook)[:\s]*$/i;
const servingsKeywords = /(?:yield|serve|servings?|makes)\s*:?\s*([\d]+)/i;
const prepTimeKeywords = /prep\s+time\s*:?\s*([\d]+)\s*(?:mins?|m|minutes?)|prep\s*:?\s*([\d]+)\s*(?:mins?|m|minutes?)/i;
const cookTimeKeywords = /cook\s+time\s*:?\s*([\d]+)\s*(?:mins?|m|minutes?)|cooking\s*:?\s*([\d]+)\s*(?:mins?|m|minutes?)/i;

// Extract title
if (!title && lines.length > 0) {
  for (const pattern of titlePatterns) {
    const match = lines[0].match(pattern);
    if (match) {
      title = match[1]?.trim() || lines[0];
      break;
    }
  }
  if (!title && !lines[0].match(/^(?:ingredients|instructions|steps|method)/i)) {
    title = lines[0];
  }
}

// Find sections and extract content
const ingredients = [];
const instructions = [];

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];

  // Check for section headers
  if (ingredientKeywords.test(line)) {
    ingredientsSectionStart = i + 1;
    instructionsSectionStart = -1;
    continue;
  }
  if (instructionKeywords.test(line)) {
    instructionsSectionStart = i + 1;
    ingredientsSectionStart = -1;
    continue;
  }

  // Extract servings
  const servingsMatch = line.match(servingsKeywords);
  if (servingsMatch) {
    servings = servingsMatch[1];
  }

  // Extract prep time
  const prepMatch = line.match(prepTimeKeywords);
  if (prepMatch) {
    prepTime = prepMatch[1] || prepMatch[2];
  }

  // Extract cook time if prep time not found
  if (prepTime === '30') {
    const cookMatch = line.match(cookTimeKeywords);
    if (cookMatch) {
      prepTime = cookMatch[1] || cookMatch[2];
    }
  }

  // Categorize line content
  if (ingredientsSectionStart > 0 && i >= ingredientsSectionStart) {
    // Stop at next section or empty line before next section
    if (instructionKeywords.test(line) || (line.length === 0 && i + 2 < lines.length && instructionKeywords.test(lines[i + 2]))) {
      ingredientsSectionStart = -1;
    } else if (line.length > 0 && !instructionKeywords.test(line)) {
      ingredients.push(line);
    }
  } else if (instructionsSectionStart > 0 && i >= instructionsSectionStart) {
    // Collect instructions
    if (line.length > 0) {
      instructions.push(line);
    }
  } else if (ingredientsSectionStart === -1 && instructionsSectionStart === -1) {
    // Before any section is identified, try to guess based on line content
    // Lines with measurements are likely ingredients
    if (/\d+\s*(?:cup|tbsp|tsp|g|kg|ml|oz|lb|lbs|dash|pinch)/i.test(line)) {
      ingredients.push(line);
    } else if (/^(?:\d+\.|-)\s+/i.test(line) && ingredients.length > 0 && instructions.length === 0) {
      // Numbered or bullet points after ingredients are likely instructions
      instructions.push(line.replace(/^(?:\d+\.|-)\s+/, ''));
    } else if (ingredients.length > 0 && line.length > 20 && !line.match(/^(?:ingredients|instructions)/i)) {
      // Longer lines after ingredients are likely instructions
      instructions.push(line);
    }
  }
}

// Format the extracted data
ingredientsText = ingredients.join('\n').trim();
instructionsText = instructions.join('\n').trim();

// Ensure we have required data
if (!title) {
  title = 'Recipe from pasted content';
}

if (!ingredientsText && !instructionsText) {
  console.error('Could not parse recipe content');
  return [{ json: { error: 'Could not parse recipe from pasted content. Please ensure the recipe includes ingredients and instructions.' } }];
}

console.log('✓ Successfully parsed recipe content');

return [{
  json: {
    title: title,
    ingredients_text: ingredientsText,
    instructions_text: instructionsText,
    servings: servings,
    prep_time: prepTime,
    image_url: undefined,
    source_url: 'pasted-content'
  }
}];
